import React from "react";
import Col from "react-bootstrap/Col";
import Card from "react-bootstrap/Card";

const ProjectCard = ({ value }) => {
  const { name, description, link, tags, status } = value;
  const isLive = status === "live";

  return (
    <Col md={6}>
      <Card className="project-card mb-4">
        <Card.Body className="d-flex flex-column">
          <div className="d-flex justify-content-between align-items-start mb-2">
            <Card.Title as="h5" className="mb-0">{name}</Card.Title>
            <span className={`status-badge ${isLive ? "status-live" : "status-soon"}`}>
              {isLive ? "Live" : "Coming soon"}
            </span>
          </div>
          <Card.Text className="flex-grow-1">{description}</Card.Text>
          {tags && tags.length > 0 && (
            <div className="mb-3">
              {tags.map((tag) => (
                <span key={tag} className="tag-badge">{tag}</span>
              ))}
            </div>
          )}
          {isLive && link ? (
            <a
              href={link}
              target="_blank"
              rel="noopener noreferrer"
              className="btn btn-project mt-auto"
            >
              Visit site <i className="fas fa-external-link-alt ms-1" />
            </a>
          ) : (
            <span className="btn btn-project btn-project-disabled mt-auto" aria-disabled="true">
              In development
            </span>
          )}
        </Card.Body>
      </Card>
    </Col>
  );
};

export default ProjectCard;
